    + '<div style="margin-top:4px;font-size:13px">Rebaja: <input type="number" class="pbr-dto" data-col="' + col + '" min="0" max="90" step="1" value="' + (pbRegla[col].dto || 0) + '" style="width:56px"> %</div></div>';
